css:
 body {
            font-family: "DejaVu Sans", sans-serif;
            font-size: 14px;
            margin: 20px;
        }
        .header-table {
            width: 100%;
            margin-bottom: 20px;
        }
        .header-logo {
            width: 40%;
            vertical-align: top;
        }
        .header-text {
            width: 80%;
            text-align: left;
            padding-left: 10px;
        }
        .section-title {
            text-align: center;
            margin: 20px 0 10px;
            text-transform: uppercase;
            text-decoration: underline;
        }
        .paragraphs {
            counter-reset: para;
        }

        .paragraphs p {
            counter-increment: para;
            font-size: 16px;
            line-height: 1.5;
            text-align: justify;
            margin: 12px 0;
            position: relative;
            padding-left: 24px;
        }

        .paragraphs p::before {
            content: counter(para) ". ";
            position: absolute;
            left: 0;
        }
        .signature {
            margin-top: 40px;
            margin-left:500px;
        }
        .footer-section {
            margin-top: 40px;
        }
        .table {
            width: 100%;
        }
h3{
    text-align:center;
}
@media only screen and (max-width: 600px) {
.signature{
   margin-top:30px;
}
}
.lastSec{
    display:flex;
}

body:last-child .print-format td img {
    width: 45% !important;
}
